/*
    Rogue Voxel on the Loose! 🟪🟣🦘 - by chronos
    ------------------------------------------------

    Vivi the Voxel was not like the other voxels...


    3D version of my "Happy Squircle!" shader: https://www.shadertoy.com/view/4cKcDc

    Features simulation free animation of bouncy physics and mushy soft body deformation,
    some nice (or garish, depending on your taste 😅 ) glow, splotches and a neon grid.
    I'm particularly satisfied with how the glow appears to come from an internal source
    and appear modulated by subsurface scattering. I think that's pretty neat 🙃

    Use mouse 🖱️ to control camera 🎥

    ------------------------------------------------
    self link: https://www.shadertoy.com/view/43dfDM
    ------------------------------------------------

*/


const float max_height = 1.5;
const float min_height = 0.5;
const float gravity = 1.5;
const float dampening_factor = 0.15;

const float s = .05; // Bounce smoothing
const float squish = 0.25;

const float PI = 3.14159265;

float sRGBencode(float C_linear) { return C_linear > 0.0031308 ? (1.055 * pow(C_linear, 1./2.4) - 0.055) : (12.92 * C_linear); }
vec3 sRGBencode(vec3 C_linear) { C_linear = clamp(C_linear, 0., 1.); return vec3(sRGBencode(C_linear.x), sRGBencode(C_linear.y), sRGBencode(C_linear.z)); }

float smax(float a, float b, float k)
{
    return log(exp(a*k) + exp(b*k))/k; 
}

vec3 smax(vec3 a, vec3 b, vec3 k)
{
    return log(exp(a*k) + exp(b*k))/k; 
}

// Barbican cosine. Just like the regular cosing, but with all the smoothness--- taken oot!
float sawcos(float x)
{
    float t = .5*x/PI-.5;
    return 4.*min(1.-fract(t), fract(t))-1.;
}

float get_height(float time)
{
    float height = max(max_height-floor(time*gravity)*dampening_factor, min_height);
    return height;
}

// *slaps function*: This little bad-boy is a parameterized parabolic arc for bouncing :)
float bounce(float time)
{
    float height = get_height(time);
    float y = 4.*pow(abs(fract(gravity*time)-.5), 2.); // Fix thanks to al-ro! Thanks!
    y = 1.-y;
    y = (sqrt(y*y + s)-sqrt(s))/(sqrt(1.+s)-sqrt(s));
    y = 1.-y;
    return y = height - (1.+height)*y;
}

const float smax_strength = 15.;

float sdBox(vec3 p)
{
    vec3 q = abs(p)-.25;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0)-.25;    
}

float get_path_radius(float time)
{
    return 3.; // This actually has to be constant in order for the 
    // Spin rotation to line up with the traveled distance
    // Otherwise, the integral on the traveled distance has to be used
    // in determining the rotation...
}

mat2 rot(float t)
{
    float c = cos(2. * PI * t), s = sin(2. * PI * t);
    return mat2(c, s, -s, c);
}

vec3 get_center(float time)
{
    float path_radius = get_path_radius(iTime);
    vec3 pos = vec3(path_radius, bounce(time)+1., 0);
    pos.xz = rot(iTime / 6.) * pos.xz;
    return pos;
}

float sdRogueVoxel(vec3 p)
{
    float sdf;
    {
    vec3 c = get_center(iTime);
    vec3 q = p-c;

    float height = get_height(iTime);
    q.xz *= 1.-sqrt(height+1.)*squish*pow(abs(cos(3.14159265 * iTime * gravity)), 32.);

    mat2 R = rot(iTime / 6.);
    q.zx = R * q.zx; // Rotate spin angle
    float t = iTime;

    float path_radius = get_path_radius(iTime);
    R = rot(path_radius * t * 2. / 6.);

    q.zy = R * q.zy; // spin

    q.xz = rot(1./16.) * q.xz; 

    sdf = sdBox(q);
    sdf = smax(sdf, -p.y, smax_strength);
    }
    return sdf;
}

float map(vec3 p)
{
    float sdf = sdRogueVoxel(p);
    sdf = min(sdf, p.y);

    return sdf;
}

// Some SDF marcher rendering functions by I. Quilez

// https://iquilezles.org/articles/rmshadows
float calcSoftshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
    // bounding volume
    float tp = (0.8-ro.y)/rd.y; if( tp>0.0 ) tmax = min( tmax, tp );

    float res = 1.0;
    float t = mint;
    for( int i=0; i<24; i++ )
    {
		float h = map( ro + rd*t );
        float s = clamp(8.0*h/t,0.0,1.0);
        res = min( res, s );
        t += clamp( h, 0.01, 0.2 );
        if( res<0.004 || t>tmax ) break;
    }
    res = clamp( res, 0.0, 1.0 );
    return res*res*(3.0-2.0*res);
}

// https://iquilezles.org/articles/normalsSDF
vec3 calcNormal( in vec3 pos )
{
#if 1
    vec2 e = vec2(1.0,-1.0)*0.5773*0.0005;
    return normalize( e.xyy*map( pos + e.xyy ) + 
					  e.yyx*map( pos + e.yyx ) + 
					  e.yxy*map( pos + e.yxy ) + 
					  e.xxx*map( pos + e.xxx ) );
#else
    // inspired by tdhooper and klems - a way to prevent the compiler from inlining map() 4 times
    vec3 n = vec3(0.0);
    for( int i=0; i<4; i++ )
    {
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        n += e*map(pos+0.0005*e);
      //if( n.x+n.y+n.z>100.0 ) break;
    }
    return normalize(n);
#endif    
}

// https://iquilezles.org/articles/nvscene2008/rwwtt.pdf
float calcAO( in vec3 pos, in vec3 nor )
{
	float occ = 0.0;
    float sca = 1.0;
    for( int i=0; i<5; i++ )
    {
        float h = 0.01 + 0.12*float(i)/4.0;
        float d = map( pos + h*nor );
        occ += (h-d)*sca;
        sca *= 0.95;
        if( occ>0.35 ) break;
    }
    return clamp( 1.0 - 3.0*occ, 0.0, 1.0 ) * (0.5+0.5*nor.y);
}


// Thanks pyblob!
float igrid(float d, float x)
{
    return floor(x) * d + min(x - floor(x), d);
}
float pulse_wave_box_filtered_inlined(float d, float w, float x)
{
    return (igrid(d, x + w / 2.) - igrid(d, x - w / 2.)) / w;
}

float grid(vec2 q, vec2 ground_ps, float thickness)
{
    q += thickness*.5;
    vec2 filtered = 
        vec2(
        pulse_wave_box_filtered_inlined(thickness, ground_ps.x, q.x),
        pulse_wave_box_filtered_inlined(thickness, ground_ps.y, q.y)
        );
    return filtered.x + filtered.y - filtered.x * filtered.y;
}

float splats(vec2 uv)
{
    vec2 p = vec2( log(length(uv)), atan(uv.y, uv.x) / PI);
	vec2 pol =  p;
    float num = 9.;
    float index = floor(fract(pol.y*.5+.5) * num);

    float size = index / (num);

    mat2 R = rot(2. * PI * fract(index * (sqrt(5.)*.5+.5)) );

    vec2 center = vec2(0, -1. + 2. * size  + 1./(num-1.));

    float ps = 2. / iResolution.y;

    size = fract(size - iTime/6. - .4471111449);
    vec2 cell_uv = R * ((pol-center) * vec2(1., PI));
    float sdf = length(cell_uv)-1.5/num * pow(size,4.);

    sdf = pow(
        dot(
            pow(abs(cell_uv), vec2(4.)),
            vec2(1)
            ), 
      1. / 4.)-1.5/num * pow(size,4.) + (cos(2. * 2. * PI * atan(cell_uv.y, cell_uv.x)))*.005;

    return sdf;
}

vec3 calcRayForPixel( vec2 coord)
{
	vec2 uv = (2.0*coord-iResolution.xy) / iResolution.y;
	vec2 mouse = (2.*iMouse.xy-iResolution.xy)/iResolution.y;
    if(length(iMouse.xy) < 10.)
    {
        mouse = vec2(-iTime*.05, 0.);
    }
    float focal = 2.;
    vec3 rd = normalize(vec3(uv, -focal));

    rd.yz = mat2(cos(-PI/16.), sin(-PI/16.), -sin(-PI/16.), cos(-PI/16.)) * rd.yz;

    float vertical_m = min(max(mouse.y, -0.7), .45) -PI/16.;
    float horizontal_m = 2. * mouse.x;
    rd.yz = mat2(cos(vertical_m), sin(vertical_m), -sin(vertical_m), cos(vertical_m)) * rd.yz;
    rd.xz = mat2(cos(horizontal_m), sin(horizontal_m), -sin(horizontal_m), cos(horizontal_m)) * rd.xz;

	return rd;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv    = (2.*fragCoord-iResolution.xy)/iResolution.y;
    vec2 mouse = (2.*iMouse.xy-iResolution.xy)/iResolution.y;
    float ps   = 2. / iResolution.y;
    vec3 color = vec3(0);

    if(length(iMouse.xy) < 10.)
    {
        mouse = vec2(-iTime*.05, 0.);
    }

    vec3 ro = vec3(0, 2, 6);

    float vertical_m = min(max(mouse.y, -0.7), .45) -PI/16.;
    float horizontal_m = 2. * mouse.x;

    vec3 rd = calcRayForPixel(fragCoord);

    ro.yz = mat2(cos(vertical_m), sin(vertical_m), -sin(vertical_m), cos(vertical_m)) * ro.yz;
    ro.xz = mat2(cos(horizontal_m), sin(horizontal_m), -sin(horizontal_m), cos(horizontal_m)) * ro.xz;

    float max_t = (-ro.y/rd.y);

    float t = texelFetch(iChannel0, (ivec2(fragCoord.xy)+iFrame*100)%1024, 0)[iFrame%4]/2.;

    const float eps = 1e-3;

    float glow_acc = 0.;
    for(int i = 0; i < 180; i++)
    {
        vec3 p = rd * t + ro;
        float rogueVoxel = sdRogueVoxel(p);
        float d = min(rogueVoxel, p.y);
        glow_acc += exp(-rogueVoxel)*.02;        
        if(d < eps) break;
        t += d;
        if((t > max_t && max_t > 0.) || t > 1e2) break;
    }

    float path_radius = get_path_radius(iTime);
    vec3 p = rd * t + ro;
    vec3 glow_color = vec3(1, 0.01,.5);
    float pulse = cos(iTime*1.333)*.5+.5;

    {
        vec3 nor = calcNormal( p );
        vec3 L = normalize(vec3(1));

        vec3 center = get_center(iTime);

        if(t >= max_t-.025 && max_t > 0.)
        {
            float grid_size = 2.;
            vec2 q = p.xz/grid_size;

            vec2 ground_ps;
            {
                vec3 ddx_rd = calcRayForPixel( fragCoord + vec2(1.0,0.0));
                vec3 ddy_rd = calcRayForPixel( fragCoord + vec2(0.0,1.0));
                float ddx_t = -ro.y/ddx_rd.y;
                float ddy_t = -ro.y/ddy_rd.y;
                vec3 ddx_pos = (ro + ddx_t * ddx_rd)/grid_size;
                vec3 ddy_pos = (ro + ddy_t * ddy_rd)/grid_size;

                ground_ps = max(abs(ddx_pos.xz-q), abs(ddy_pos.xz-q)) + 0.02;
            }

            vec2 ground_uv = fract(q);

            color = 0.05 * pow(texture(iChannel1, ground_uv).ggg, vec3(2.2));

            vec3 grid_color  = glow_color.zxy;
            grid_color.xz = rot(iTime/20.) * grid_color.xz;

            color *= 1.- grid(q, ground_ps, 0.1);

            vec3 grid_glow = vec3(0);

            grid_glow += grid(q, ground_ps, 0.05) * grid_color;

            vec2 grid_distXY = min(ground_uv, 1.-ground_uv);
            float grid_dist = min(grid_distXY.x, grid_distXY.y);

            color *= mix(1., calcSoftshadow(p, L, 0.02, 2.5), .25);

            if(floor(q) == floor(center.xz/grid_size))
            {
                grid_glow += 
                    grid_color*smoothstep(1., 0.25, center.y)
                    *
                    mix(1., 
                    (cos(2. * (ground_uv.x-.5) * PI) * .5 + .5)
                    *
                    (cos(2. * (ground_uv.y-.5) * PI) * .5 + .5)
                    ,
                    .85)
                    ;
            }

            grid_glow += grid_color * .0075/ max(0.01, grid_dist) * max(1.-.075*length(q), 0.);

            float fade_in0 = clamp((iTime-1.)*.1, 0., 1.);
            float fade_in1 = clamp((iTime-3.)*.05, 0., 1.);
            color += fade_in1 * grid_glow;

            float gps = length(ground_ps);
            float splat_sdf = splats(p.xz/path_radius)*path_radius;

            float splat_tex = mix(1., pow(texture(iChannel1, ground_uv).ggg, vec3(2.2)).g, 0.9);

            float splat_alpha = .5*smoothstep(0.15, 0.05, splat_sdf+0.15)
                * splat_tex
                ;

            color = mix(color, glow_color, fade_in0 * splat_alpha);
            color += fade_in0 * splat_tex * pow(tanh(exp(-5. * splat_sdf)),4.) * glow_color;
        }
        else
        {
            color = vec3(.05) * mix(max(dot(nor, L), 0.), 1., .3);

            float radius = .45;
            color += 1.*pulse * glow_color * 0.1 * pow(1. / max(length(center - p) - radius, 1e-5), 1.6);
        }

        color *= mix(1., calcAO( p, nor), .75);

        color += 
            max(normalize(center+vec3(0,0.75,0) - p).y , 0.) *    /// Cosine term with offset to center to bias away from reaching zero
            pulse * glow_color * 0.5 * 1. / max(length(center - p), 1e-5);
    }

    color *= exp(-t*.075);

    color += pulse * glow_color * glow_acc;

    color *= 1.-.1*dot(uv, uv);

    color = max(color, 0.);

    float contrast = 1.5;
    color = tanh(contrast * pow(color, vec3(contrast)));

    fragColor = vec4(sRGBencode(color), 1.0) + texelFetch(iChannel0, ivec2(fragCoord.xy)%1024, 0)/255.;
}
